-- ForeverQuests: a história de Tanaris (mapa 1446), escrita para este addon.
-- Contexto histórico: Warcraft Wiki (warcraft.wiki.gg/wiki/Tanaris_(Classic)).
local _, ns = ...

ns.LZ = ns.LZ or {}
ns.LZ_EN = ns.LZ_EN or {}
ns.LC = ns.LC or {}
ns.LC_EN = ns.LC_EN or {}
ns.LQ2 = ns.LQ2 or {}
ns.LQ2_EN = ns.LQ2_EN or {}

ns.LZ[1446] = "Um mar de areia no sudeste de Kalimdor, varrido por tempestades, onde quase nada cresce. Nem sempre foi assim: antes do Grande Cataclismo, isto era selva, terra de tribos taurens e do império troll Gurubashi. Quando o continente se partiu, a selva virou deserto, e os trolls Farraki que ficaram presos aqui se adaptaram, viraram trolls da areia e ergueram Zul'Farrak, no noroeste. Nas montanhas do leste, o dragão bronze Nozdormu guarda as Cavernas do Tempo, e sob as dunas do sul dormem as ruínas de Uldum, obra dos titãs.\n\nOs goblins do Cartel Steamwheedle chegaram depois e fizeram do deserto o seu quintal: Geringontzan, no centro, é neutra, guardada por leões de chácara que não deixam Horda e Aliança brigarem dentro dos muros, e o Porto de Bondebico, no litoral, recebe navios da Angra do Butim e de Porto Detonapavio. Aqui tudo tem preço, inclusive a água.\n\nO que está acontecendo agora: os nômades Errantes tomaram quase todos os poços, e a Companhia de Águas de Geringontzan está desesperada. No sul, insetos silitídeos brotaram da areia, secam os oásis e parecem obedecer a uma vontade de fora — o primeiro sinal da ameaça de Ahn'Qiraj. Piratas dos Mares do Sul saqueiam a costa a partir de uma enseada fortificada, os ogros Dunamalho montaram um complexo no sul e os trolls de Zul'Farrak não deixam ninguém chegar perto. E, nas Cavernas do Tempo, Anacronos, da revoada bronze, observa e espera a hora de abrir os portões de Ahn'Qiraj."
ns.LZ_EN[1446] = "A sea of sand in southeastern Kalimdor, swept by storms, where almost nothing grows. It was not always like this: before the Great Sundering this was jungle, home to tauren tribes and to the troll empire of the Gurubashi. When the continent broke apart the jungle became desert, and the Farraki trolls stranded here adapted, became sand trolls and raised Zul'Farrak in the northwest. In the eastern mountains the bronze dragon Nozdormu guards the Caverns of Time, and beneath the southern dunes sleep the ruins of Uldum, built by the titans.\n\nThe goblins of the Steamwheedle Cartel came later and made the desert their backyard: Gadgetzan, in the middle, is neutral, guarded by bruisers who will not let Horde and Alliance fight inside the walls, and Steamwheedle Port, on the coast, takes ships from Booty Bay and Powderfuse Port. Here everything has a price, water included.\n\nWhat is happening now: the Wastewander nomads have seized almost every well, and the Gadgetzan Water Company is desperate. In the south, silithid insects have burst out of the sand, drain the oases and seem to obey a will from somewhere else — the first sign of the threat of Ahn'Qiraj. Southsea pirates raid the coast from a fortified cove, the Dunemaul ogres have built a compound in the south, and the trolls of Zul'Farrak let no one near. And in the Caverns of Time, Anachronos of the bronze flight watches and waits for the hour to open the gates of Ahn'Qiraj."

ns.LC[95472] = "O outro lado do contrabando de Powderfuse. A mercadoria secreta de Friz Faiscansa atravessa o mar até o Porto de Bondebico, onde um goblin chamado Tazzik deveria recebê-la. Deveria."
ns.LC_EN[95472] = "The other end of Powderfuse's smuggling. Friz Frazzlespark's secret goods cross the sea to Steamwheedle Port, where a goblin named Tazzik is supposed to collect them. Supposed to."
ns.LC[32] = "A água de Tanaris está sumindo, e não são só os nômades. A Companhia de Águas de Geringontzan manda um topógrafo atrás de poças novas e descobre insetos que bebem o deserto — e que não agem sozinhos. É o começo da ameaça silitídea."
ns.LC_EN[32] = "Tanaris's water is vanishing, and not only because of the nomads. The Gadgetzan Water Company sends a surveyor after new pools and finds insects that drink the desert dry — and do not act alone. It is the beginning of the silithid threat."
ns.LC[654] = "A Sociedade Real de Boticários, em Undercity, quer amostras de tecido das feras do deserto, e o kit de testes precisa de uma fonte de energia goblin. Em Geringontzan, nada é de graça."
ns.LC_EN[654] = "The Royal Apothecary Society in the Undercity wants tissue samples from the desert's beasts, and the testing kit needs a goblin power source. In Gadgetzan, nothing is free."
ns.LC[1691] = "Os nômades Errantes tomaram os poços que mantêm Geringontzan viva. O Engenheiro-chefe Silvadágua quer a água de volta, e a justiça dele é medida em nômades derrubados."
ns.LC_EN[1691] = "The Wastewander nomads have seized the wells that keep Gadgetzan alive. Chief Engineer Bilgewhizzle wants the water back, and his justice is measured in fallen nomads."
ns.LC[1878] = "Cada bolsa de água dos Errantes foi, um dia, água de Geringontzan. O Operador de Torneira Rastamala paga por elas de volta."
ns.LC_EN[1878] = "Every Wastewander water pouch was once Gadgetzan's water. Spigot Operator Luglunket pays to have them back."
ns.LC[3520] = "Yeh'kinya, um troll velho no Porto de Bondebico, fala de um deus antigo e dos primos dele nas florestas de Feralas. Ele diz não acreditar na profecia. Mas quer muito os espíritos."
ns.LC_EN[3520] = "Yeh'kinya, an old troll in Steamwheedle Port, speaks of an ancient god and his cousins in the forests of Feralas. He says he does not believe the prophecy. But he wants those spirits very badly."
ns.LC[2874] = "Uma aposta entre dois bebedores: MacKinley, da Angra do Butim, e Esmirno, do Porto de Bondebico. Em jogo, a honra do rum de cada lado do mar — e o rum foi roubado por piratas."
ns.LC_EN[2874] = "A wager between two drinkers: MacKinley of Booty Bay and Stoley of Steamwheedle Port. At stake, the honour of the rum on each side of the sea — and the rum has been stolen by pirates."
ns.LC[8182] = "Yeh'kinya mostrou quem era. O Prospector Botaférrea entende o que isso significa: Hakkar, o Esfolador de Almas, está voltando, e só os trolls Zandalari talvez saibam detê-lo."
ns.LC_EN[8182] = "Yeh'kinya has shown his true colours. Prospector Ironboot understands what it means: Hakkar the Soulflayer is returning, and only the Zandalari trolls might know how to stop him."
ns.LC[2747] = "Os hipogrifos de Feralas estão sumindo, e um gnomo de Geringontzan inventou uma máquina para salvar os ovos que restam. O que sai do Ovomático depende da sorte."
ns.LC_EN[2747] = "Feralas's hippogryphs are dwindling, and a gnome in Gadgetzan has built a machine to save the eggs that are left. What comes out of the Egg-O-Matic is down to luck."
ns.LC[648] = "Um ovo de metal na areia acorda com a voz de Olhatorto Obnótico, um gnomo da Angra do Butim que perdeu o robô teleguiado no deserto."
ns.LC_EN[648] = "A metal egg in the sand wakes up with the voice of Oglethorpe Obnoticus, a Booty Bay gnome who lost his homing robot in the desert."
ns.LC[2662] = "Marin Nublacuca tem sede, e quando um goblin tem sede, ele inventa uma bebida e tenta vender. Assim nasce o famoso Elixir Nublacuca."
ns.LC_EN[2662] = "Marin Noggenfogger is thirsty, and when a goblin is thirsty he invents a drink and tries to sell it. So the famous Noggenfogger Elixir is born."
ns.LC[2954] = "Os discos de Norgannon, trazidos de Uldaman, acordam um guardião de pedra no deserto. Ele vigia a entrada de Uldum e não abre para quem não tiver as placas certas."
ns.LC_EN[2954] = "The discs of Norgannon, brought from Uldaman, wake a stone guardian in the desert. He watches the entrance to Uldum and will not open it to anyone without the right plates."
ns.LC[3444] = "Marlon Catarrebite já esteve no Templo Submerso e quase não voltou. Uma pedra com o símbolo da serpente pode ser a chave do que ele viu lá dentro."
ns.LC_EN[3444] = "Marvon Rivetseeker has been inside the Sunken Temple and barely came back. A stone bearing the serpent symbol may be the key to what he saw there."
ns.LC[4509] = "Os silitídeos são como abelhas, conclui o Alquimista Almofarrista: mate a rainha, e a colmeia se desorganiza. A caçada vai até a colmeia Gorishi, na Cratera Un'Goro."
ns.LC_EN[4509] = "The silithid are like bees, Alchemist Pestlezugg concludes: kill the queen and the hive falls into disarray. The hunt goes to the Gorishi hive in Un'Goro Crater."
ns.LC[5802] = "A chave-mestra de Scolomântia precisa de um calor que nenhuma forja comum alcança. Rugov A. Massoaço vende o molde; o resto é com o vulcão."
ns.LC_EN[5802] = "The Scholomance skeleton key needs a heat no ordinary forge can reach. Krinkle Goodsteel sells the mould; the rest is up to the volcano."
ns.LC[8928] = "Mux Zoamana, um engenheiro obcecado pelo sobrenatural, quer construir uma máquina que revela fantasmas. O projeto custa caro, viaja longe e termina na loja de um diabrete."
ns.LC_EN[8928] = "Mux Manascrambler, an engineer obsessed with the supernatural, wants to build a machine that reveals ghosts. The project costs a lot, travels far and ends at an imp's shop."
ns.LC[8766] = "A Prole de Nozdormu reconhece quem luta em Ahn'Qiraj. No caminho do conquistador, o anel de Anacronos cresce com a sua reputação."
ns.LC_EN[8766] = "The Brood of Nozdormu recognises those who fight in Ahn'Qiraj. On the path of the conqueror, Anachronos's ring grows with your standing."
ns.LC[8765] = "A Prole de Nozdormu reconhece quem luta em Ahn'Qiraj. No caminho do evocador, o anel de Anacronos cresce com a sua reputação."
ns.LC_EN[8765] = "The Brood of Nozdormu recognises those who fight in Ahn'Qiraj. On the path of the invoker, Anachronos's ring grows with your standing."
ns.LC[8764] = "A Prole de Nozdormu reconhece quem luta em Ahn'Qiraj. No caminho do protetor, o anel de Anacronos cresce com a sua reputação."
ns.LC_EN[8764] = "The Brood of Nozdormu recognises those who fight in Ahn'Qiraj. On the path of the protector, Anachronos's ring grows with your standing."
ns.LC[8728] = "Azuregos pediu uma boia de arcanita, e só um gnomo em Tanaris consegue fazê-la: Narain Suavestilo, vidente, excêntrico e incapaz de ler dracônico. Antes da boia vêm os óculos roubados, um frango de 250 quilos e um livro sequestrado."
ns.LC_EN[8728] = "Azuregos asked for an arcanite buoy, and only one gnome in Tanaris can make it: Narain Soothfancy, seer, eccentric and unable to read Draconic. Before the buoy come the stolen goggles, a five-hundred-pound chicken and a kidnapped book."
ns.LC[9251] = "Atiesh, o grande cajado do Guardião, quase inteiro e ainda corrompido pelo mal de Sargeras. Anacronos sabe onde estão as peças que faltam."
ns.LC_EN[9251] = "Atiesh, the Guardian's greatstaff, nearly whole and still tainted by Sargeras's evil. Anachronos knows where the missing pieces are."
ns.LC[8742] = "Mil anos depois, o Cetro das Areias Movediças volta a ficar inteiro, e quem o reuniu toca o gongo que abre Ahn'Qiraj."
ns.LC_EN[8742] = "A thousand years on, the Scepter of the Shifting Sands is whole again, and whoever rebuilt it will ring the gong that opens Ahn'Qiraj."
ns.LC[8555] = "Para refazer o cetro, Anacronos manda você atrás de três dragões que um dia vigiaram o mundo: Eranikus, Vaelastrasz e Azuregos. Cada um caiu numa tragédia diferente."
ns.LC_EN[8555] = "To remake the scepter, Anachronos sends you after three dragons who once watched over the world: Eranikus, Vaelastrasz and Azuregos. Each fell to a different tragedy."

ns.LQ2[95144] = { "O Estalajadeiro Gabor Bulho, de Geringontzan, tem um caixote misterioso que precisa atravessar o mar. O destino é Porto Detonapavio, nas Riverglades, onde Friz Faiscansa espera. Ninguém pergunta o que tem dentro.",
    "Friz recebe o caixote com um sorriso largo demais. Você não pergunta. Ele não conta." }
ns.LQ2_EN[95144] = { "Innkeeper Fizzgrimble of Gadgetzan has a mysterious crate that needs to cross the sea. Its destination is Powderfuse Port in the Riverglades, where Friz Frazzlespark is waiting. Nobody asks what is inside.",
    "Friz takes the crate with a grin a little too wide. You don't ask. He doesn't tell." }
ns.LQ2[95383] = { "O frete de Friz chegou ao Porto de Bondebico, e o Mestre Portuário Vaporeto quer o pacote longe do cais o quanto antes. A mercadoria secreta deve ser entregue a Tazzik, o contato de Friz deste lado do mar.",
    "Tazzik pega a encomenda rápido demais e já tem uma desculpa pronta para o pagamento." }
ns.LQ2_EN[95383] = { "Friz's freight has reached Steamwheedle Port, and Wharfmaster Steamfizzle wants the package off his docks as soon as possible. The secret goods go to Tazzik, Friz's contact on this side of the sea.",
    "Tazzik takes the parcel a little too quickly and already has an excuse ready about the payment." }
ns.LQ2[95312] = { "Tazzik diz que o dinheiro de Friz está com outro goblin: Fizbuz Mithril, em Geringontzan. Basta ir lá receber. Parece simples. Com goblins, nunca é.",
    "Fizbuz ri na sua cara: Tazzik não tem crédito nenhum com ele. Pelo contrário, deve." }
ns.LQ2_EN[95312] = { "Tazzik says Friz's money is with another goblin: Fizbuz Mithril, in Gadgetzan. Just go and collect it. It sounds simple. With goblins, it never is.",
    "Fizbuz laughs in your face: Tazzik has no credit with him. Quite the opposite, he owes." }
ns.LQ2[95321] = { "Fizbuz deixa claro que Tazzik deve dinheiro para meio Tanaris. Você volta ao Porto de Bondebico para ter uma conversa séria com o contato de Friz.",
    "Encurralado, Tazzik admite que gastou tudo. O que sobra para pagar Friz é pouco — muito pouco." }
ns.LQ2_EN[95321] = { "Fizbuz makes it clear that Tazzik owes money to half of Tanaris. You go back to Steamwheedle Port for a serious word with Friz's contact.",
    "Cornered, Tazzik admits he spent the lot. What is left to pay Friz with is little — very little." }
ns.LQ2[95472] = { "Sem um tostão, Tazzik oferece a única coisa que tem: a camisa do corpo, encharcada de suor. Como prêmio de consolação para Friz, é o que há.",
    "Friz segura a camisa com dois dedos, longe do nariz, e jura que nunca mais faz negócio com Tazzik." }
ns.LQ2_EN[95472] = { "Without a coin to his name, Tazzik offers the only thing he has: the shirt off his back, soaked in sweat. As a consolation prize for Friz, it is what there is.",
    "Friz holds the shirt between two fingers, well away from his nose, and swears he will never deal with Tazzik again." }
ns.LQ2[1690] = { "O Engenheiro-chefe Silvadágua não tem paciência: os nômades Errantes tomaram quase todos os poços do deserto, e sem eles Geringontzan seca. A leste da cidade, bandidos e ladrões vigiam a água roubada.",
    "Silvadágua aprova a eficiência. Os nômades estão mais fracos, mas a briga pelos poços só começou." }
ns.LQ2_EN[1690] = { "Chief Engineer Bilgewhizzle has no patience left: the Wastewander nomads have seized almost every well in the desert, and without them Gadgetzan dries up. East of town, bandits and thieves guard the stolen water.",
    "Bilgewhizzle approves of the efficiency. The nomads are weaker, but the fight for the wells has only begun." }
ns.LQ2[1691] = { "Agora é a vez dos Errantes que mandam de verdade: magos das sombras, ladinos e assassinos, a leste e a sudeste. Silvadágua não mente: são gente ruim.",
    "Com o bando reduzido, a Companhia de Águas finalmente pode levar a briga até os poços. E o operador da torneira paga pelas bolsas de água que você trouxer." }
ns.LQ2_EN[1691] = { "Now it is the turn of the Wastewanders who really run things: shadow mages, rogues and assassins, to the east and southeast. Bilgewhizzle won't lie to you: they are a nasty lot.",
    "With the band cut down, the Water Company can finally take the fight to the wells. And the spigot operator pays for any water pouches you bring." }
ns.LQ2[2781] = { "Um cartaz em Geringontzan oferece uma recompensa alta pela cabeça de Califa Escorpicada, o líder dos Errantes: assassinato de funcionários, roubo de água, ocupação de propriedade da Companhia.",
    "A cabeça do califa chega à mesa de Silvadágua. Justiça feita, diz ele, e talvez seja o empurrão que faltava para tirar os nômades dos poços." }
ns.LQ2_EN[2781] = { "A poster in Gadgetzan offers a high bounty for the head of Caliph Scorpidsting, leader of the Wastewanders: murder of employees, theft of water, seizure of Company property.",
    "The caliph's head lands on Bilgewhizzle's desk. Justice is served, he says, and perhaps it is the push needed to drive the nomads off the wells." }
ns.LQ2[1707] = { "O Operador de Torneira Rastamala lembra que a água nas bolsas dos Errantes era de Geringontzan antes de ser roubada. Para cada cinco que voltarem, a Companhia paga um pacote oficial.",
    "Quanto mais água volta, mais longe fica o desastre. Rastamala quer mais." }
ns.LQ2_EN[1707] = { "Spigot Operator Luglunket points out that the water in the Wastewander pouches belonged to Gadgetzan before it was stolen. For every five that come back, the Company pays an official care package.",
    "The more water comes back, the further away disaster gets. Luglunket wants more." }
ns.LQ2[1878] = { "Mais cinco bolsas de água dos Errantes, mais um pacote da Companhia. Rastamala nunca se cansa de receber.",
    "Rastamala conta as bolsas, carimba o recibo e pede mais." }
ns.LQ2_EN[1878] = { "Five more Wastewander water pouches, one more Company package. Luglunket never tires of receiving them.",
    "Luglunket counts the pouches, stamps the receipt and asks for more." }
ns.LQ2[992] = { "A Companhia de Águas precisa de fontes novas, e o Topógrafo Sênior Secamolha contrata você como topógrafo júnior temporário. Com um treco de coleta na mão, você vai tirar uma amostra da poça perto do Posto Silitriste, bem à vista dos trolls.",
    "Uma criatura estranha atacou você na poça, e Secamolha empalidece: ele tinha ouvido falar de insetos que sugam a água do deserto e achou que era invenção dos nômades. Não era." }
ns.LQ2_EN[992] = { "The Water Company needs new sources, and Senior Surveyor Fizzledowser hires you as a temporary junior surveyor. With a dowsing widget in hand, you go to sample the pool near Sandsorrow Watch, in full view of the trolls.",
    "Something strange attacked you at the pool, and Fizzledowser goes pale: he had heard of insects sucking the desert's water dry and thought it was a nomad story. It wasn't." }
ns.LQ2[82] = { "Os insetos estão drenando as poças onde hoje fica o Covil Nóxio, e é só isso que se sabe. Secamolha quer pedaços dos centiparte para o Alquimista Almofarrista descobrir o que eles são.",
    "Almofarrista examina os pedaços e não reconhece nada: parece que esses bichos são controlados por uma força de fora. E Secamolha tem uma emergência." }
ns.LQ2_EN[82] = { "The insects are draining the pools where the Noxious Lair now lies, and that is all anyone knows. Fizzledowser wants Centipaar parts so Alchemist Pestlezugg can work out what they are.",
    "Pestlezugg examines the parts and recognises nothing: it is as if these creatures are being controlled by something outside. And Fizzledowser has an emergency." }
ns.LQ2[10] = { "O melhor assistente de Secamolha, o Topógrafo Júnior Caranduru, foi mandado ao grande abismo a sudeste e sumiu. O último relatório dele falava de mais insetos. Secamolha pede que você o encontre — ou pelo menos o equipamento.",
    "Só o equipamento voltou. Secamolha lamenta o goblin e torce para que os dados dele valham alguma coisa: os insetos são espertos demais, como se alguém os guiasse." }
ns.LQ2_EN[10] = { "Fizzledowser's best assistant, Junior Surveyor Scrimshank, was sent into the great chasm to the southeast and vanished. His last report mentioned more insects. Fizzledowser asks you to find him — or at least his equipment.",
    "Only the equipment came back. Fizzledowser mourns the goblin and hopes his readings are worth something: the bugs are far too cunning, as if someone were steering them." }
ns.LQ2[110] = { "Enquanto Secamolha cuida das coisas de Caranduru, ele te manda ver se Almofarrista já terminou a análise dos pedaços.",
    "O resultado é inquietante: os insetos foram transformados em devastadores puros por uma força poderosa e maligna." }
ns.LQ2_EN[110] = { "While Fizzledowser sees to Scrimshank's belongings, he sends you to check whether Pestlezugg has finished analysing the parts.",
    "The result is unsettling: the insects have been turned into pure ravagers by a powerful and malignant force." }
ns.LQ2[113] = { "Almofarrista quer o relatório nas mãos de Secamolha agora — e uma cópia para você espalhar. A ameaça não é só de Tanaris: é de todo o sul de Kalimdor, talvez de Azeroth.",
    "Secamolha não gosta de dar informação de graça, mas confia no alquimista. Faz a cópia e te paga como topógrafo júnior." }
ns.LQ2_EN[113] = { "Pestlezugg wants the report in Fizzledowser's hands right now — and a copy for you to spread around. The threat is not just to Tanaris: it is to all of southern Kalimdor, perhaps to Azeroth.",
    "Fizzledowser doesn't like giving information away, but he trusts the alchemist. He makes the copy and pays you as a junior surveyor." }
ns.LQ2[32] = { "Com o relatório na mão, Secamolha te manda a quem entende do assunto: Zilzibin Tamborleiro, um troll estudioso que mora no Arrasto, em Orgrimmar.",
    "Zilzibin reconhece as criaturas na hora: silitídeos. Uma das maiores ameaças que Horda e Aliança vão enfrentar — e ninguém quis ver antes." }
ns.LQ2_EN[32] = { "Report in hand, Fizzledowser sends you to someone who knows the subject: Zilzibin Drumlore, a troll scholar who lives on the Drag in Orgrimmar.",
    "Zilzibin recognises the creatures at once: silithid. One of the greatest threats Horde and Alliance will ever face — and no one wanted to see it sooner." }
ns.LQ2[4496] = { "A pesquisa de Almofarrista mostra que os silitídeos são como abelhas: sem a rainha, a colmeia se desfaz. Para atraí-la, ele precisa de uma glândula odorífera de um inseto Gorishi e de terra de Un'Goro.",
    "A membrana está intacta, a terra serve. Almofarrista mói tudo e prepara a isca." }
ns.LQ2_EN[4496] = { "Pestlezugg's research shows the silithid are like bees: without the queen, the hive falls apart. To lure her out he needs a scent gland from a Gorishi insect and some Un'Goro soil.",
    "The membrane is intact, the soil will do. Pestlezugg grinds it all down and prepares the lure." }
ns.LQ2[4507] = { "Dentro da colmeia Gorishi há um cristal que os insetos usam para se sintonizar. Usando a isca nele, a rainha aparece — com guarda. Almofarrista quer o cérebro dela para estudar.",
    "A rainha cai, e o cérebro vai para os frascos de Almofarrista. Ele comemora, mas desconfia: foi limpo demais. Os silitídeos não acabaram." }
ns.LQ2_EN[4507] = { "Inside the Gorishi hive is a crystal the insects use to attune themselves. Use the lure on it and the queen comes out — with guards. Pestlezugg wants her brain to study.",
    "The queen falls, and her brain goes into Pestlezugg's jars. He celebrates, but is suspicious: that was too clean. The silithid are not finished." }
ns.LQ2[4509] = { "O que se aprendeu em Un'Goro precisa chegar a quem pode agir. Almofarrista manda o relatório a Zilzibin, em Orgrimmar, que tem amigos importantes na Horda.",
    "Zilzibin agradece, mas não se ilude: a Horda só enxerga a Aliança, e Thrall está cercado de maus conselhos. Ainda assim, vocês dois viram a ameaça. É preciso continuar." }
ns.LQ2_EN[4509] = { "What was learned in Un'Goro has to reach someone who can act. Pestlezugg sends the report to Zilzibin in Orgrimmar, who has friends high in the Horde.",
    "Zilzibin is grateful but under no illusions: the Horde only sees the Alliance, and Thrall is surrounded by bad advice. Still, the two of you have seen the threat. You have to keep going." }
ns.LQ2[243] = { "A Boticária Zilda, em Undercity, quer amostras do tecido de basiliscos, escorpiões e hienas de Tanaris. O kit de testes precisa de uma fonte de energia que só os goblins de Geringontzan têm, e é com o Engenheiro-chefe Silvadágua que se negocia.",
    "Silvadágua tem fontes de sobra — graças aos nômades, os poços estão parados. Mas não vai dar nada de graça." }
ns.LQ2_EN[243] = { "Apothecary Zinge in the Undercity wants tissue samples from Tanaris's basilisks, scorpids and hyenas. The testing kit needs a power source only Gadgetzan's goblins have, and Chief Engineer Bilgewhizzle is the one to bargain with.",
    "Bilgewhizzle has spares — thanks to the nomads, the wells stand idle. But he won't give anything away." }
ns.LQ2[379] = { "O preço da fonte de energia é sede: Silvadágua quer cinco bolsas de água dos Errantes. E pergunta, com ironia, se você pretende pedir educadamente aos nômades.",
    "A fonte é sua — mas aguenta duas horas no kit. Depois disso, os dados viram fumaça." }
ns.LQ2_EN[379] = { "The price of the power source is thirst: Bilgewhizzle wants five Wastewander water pouches. And asks, dryly, whether you plan to ask the nomads nicely.",
    "The power source is yours — but it lasts two hours in the kit. After that, the data goes up in smoke." }
ns.LQ2[654] = { "Ligada, a fonte faz o kit brilhar e vibrar. O relógio começou: duas horas para conseguir amostras boas de oito basiliscos, oito hienas e oito escorpiões.",
    "Silvadágua desliga a fonte com cuidado. Os dados estão a salvo, e a Boticária vai ter as amostras." }
ns.LQ2_EN[654] = { "Once switched on, the source makes the kit glow and hum. The clock has started: two hours to get good samples from eight basilisks, eight hyenas and eight scorpids.",
    "Bilgewhizzle shuts the source down carefully. The data is safe, and the Apothecary will have her samples." }
ns.LQ2[841] = { "O tempo acabou, ou o kit caiu na areia. Silvadágua vende outra fonte — agora por dez bolsas de água. Os tempos estão difíceis para todo mundo.",
    "Outra fonte, outra chance. Silvadágua recomenda usar direito desta vez." }
ns.LQ2_EN[841] = { "Time ran out, or the kit fell in the sand. Bilgewhizzle will sell another source — for ten water pouches this time. Times are hard for everyone.",
    "Another source, another chance. Bilgewhizzle recommends using it properly this time." }
ns.LQ2[2605] = { "Marin Nublacuca tem uma sede terrível e uma ideia: no jardim de cactos a sudoeste vivem criaturas que guardam orvalho em glândulas. Com uma dessas, ele acha que faz a bebida perfeita.",
    "Marin bebe direto da glândula — e faz cara feia." }
ns.LQ2_EN[2605] = { "Marin Noggenfogger has a terrible thirst and an idea: in the cactus garden to the southwest live creatures that store dew in glands. With one of those, he reckons he can make the perfect drink.",
    "Marin drinks straight from the gland — and pulls a face." }
ns.LQ2[2606] = { "O orvalho é horrível, mas Marin não desiste. Talvez Sguisha, a melhor cozinheira de Geringontzan, saiba como fazer aquilo descer melhor — e, de preferência, com algum efeito.",
    "Sguisha suspira: Marin é um bom sujeito, só um pouco excêntrico. E precisa da ajuda dela de novo." }
ns.LQ2_EN[2606] = { "The dew is awful, but Marin won't give up. Perhaps Sprinkle, Gadgetzan's best cook, knows how to make it go down easier — and, ideally, with a bit of a kick.",
    "Sprinkle sighs: Marin is a good sort, just a little eccentric. And he needs her help, again." }
ns.LQ2[2641] = { "O segredo de Sguisha vem da infância, quando a irmã cozinhava mal: um cogumelo chamado Tragão Violeta, que só cresce debaixo d'água, num lago pequeno de Hinterlândia.",
    "É esse mesmo, diz Sguisha — e finge que vai comer." }
ns.LQ2_EN[2641] = { "Sprinkle's secret dates from childhood, when her sister cooked so badly: a mushroom called the Violet Tragan, which grows only underwater, in a small lake in the Hinterlands.",
    "That's the one, says Sprinkle — and pretends she's about to eat it." }
ns.LQ2[2661] = { "Sguisha transforma o cogumelo num pó violeta e manda entregar a Marin, com um recado: ele fica devendo um favor.",
    "Marin aceita o pó sem medo: pior do que estava não fica." }
ns.LQ2_EN[2661] = { "Sprinkle turns the mushroom into a violet powder and sends it to Marin, with a message: he owes her one.",
    "Marin takes the powder without fear: it can't get any worse." }
ns.LQ2[2662] = { "Marin mistura o pó ao orvalho e pede um minuto. O Elixir Nublacuca está para nascer.",
    "Marin te dá a primeira dose, sonha com milhões e pede que você saia da frente da clientela. Favor para Sguisha? Que piadista." }
ns.LQ2_EN[2662] = { "Marin mixes the powder into the dew and asks for a minute. The Noggenfogger Elixir is about to be born.",
    "Marin hands you the first dose, dreams of millions and asks you to stop blocking the customers. A favour for Sprinkle? Such a kidder." }
ns.LQ2[3362] = { "Tran'rek quer entrar no Vale Moitagulhas, mas não confia nas criaturas espinhosas de lá. Se você limpar o caminho, ele promete pensar em voltar.",
    "Tran'rek ouve o tamanho dos bichos e começa a repensar o plano. Mas paga o combinado." }
ns.LQ2_EN[3362] = { "Tran'rek wants to get into Thistleshrub Valley, but he doesn't trust the thorny creatures there. If you clear the way, he promises to think about going back.",
    "Tran'rek hears how big the creatures are and starts rethinking his plan. But he pays what was agreed." }
ns.LQ2[4504] = { "Tran'rek tem mais uma ideia para ganhar ouro rápido: piche supergrudento, tirado das criaturas-planta das poças de piche de Un'Goro.",
    "As mãos de Tran'rek grudam uma na outra. Ele não se abala: o dinheiro de verdade está no removedor." }
ns.LQ2_EN[4504] = { "Tran'rek has another get-rich-quick idea: super sticky tar, taken from the plant creatures by the tar pits of Un'Goro.",
    "Tran'rek's hands stick together. He is undaunted: the real money is in the remover." }
ns.LQ2[5863] = { "Um bando grande de ogros nômades chegou a Tanaris e ergueu o Complexo Dunamalho ao sul. Andi Lynn quer o complexo destruído antes que eles se organizem, começando pelo líder, Gor'marok, o Assolador.",
    "Sem Gor'marok, os ogros perdem a cabeça. Andi Lynn agradece, aliviada." }
ns.LQ2_EN[5863] = { "A large band of nomadic ogres has arrived in Tanaris and built the Dunemaul Compound to the south. Andi Lynn wants it destroyed before they organise, starting with their leader, Gor'marok the Ravager.",
    "Without Gor'marok, the ogres lose their head. Andi Lynn thanks you, relieved." }
ns.LQ2[97534] = { "Quim, em Geringontzan, faz negócio com o que a areia devolve: restos de caravanas, peças de máquinas, sucata enterrada. Ela quer sete pedaços de destroços do deserto, e não pergunta de onde vêm.",
    "Quim separa os destroços como quem conta moedas. Para ela, tudo isso ainda vale alguma coisa." }
ns.LQ2_EN[97534] = { "Quinn, in Gadgetzan, trades in whatever the sand gives back: caravan wreckage, machine parts, buried scrap. She wants seven pieces of desert debris, and doesn't ask where they come from.",
    "Quinn sorts the debris like someone counting coins. To her, all of it is still worth something." }
ns.LQ2[2741] = { "Um ovo de hipogrifo de Feralas na mão e o Ovomático na frente. A máquina pesa, mede e embala — e diz o que você tem.",
    "Bipes, estalos, e o ovo sai embalado. Agora é levar a Crista Dapinote." }
ns.LQ2_EN[2741] = { "A Feralas hippogryph egg in hand, and the Egg-O-Matic in front of you. The machine weighs, measures and packs it — and tells you what you've got.",
    "Beeps, clanks, and the egg comes out packaged. Now take it to Curgle Cranklehop." }
ns.LQ2[8893] = { "Outro ovo de hipogrifo, outra vez no Ovomático.",
    "O ovo sai pesado, medido e embalado." }
ns.LQ2_EN[8893] = { "Another hippogryph egg, back into the Egg-O-Matic.",
    "The egg comes out weighed, measured and packaged." }
ns.LQ2[2747] = { "O Ovomático disse: extraordinário. Um ovo assim é raro.",
    "Crista Dapinote mal acredita — e pede que você lembre do bem que fez hoje." }
ns.LQ2_EN[2747] = { "The Egg-O-Matic says: extraordinary. An egg like this is rare.",
    "Curgle Cranklehop can hardly believe it — and asks you to remember the good you did today." }
ns.LQ2[2748] = { "O Ovomático disse: um ovo bom, saudável.",
    "O ovo vai para Darnassus, onde deve chocar em breve." }
ns.LQ2_EN[2748] = { "The Egg-O-Matic says: a fine, healthy egg.",
    "The egg is going to Darnassus, where it should soon hatch." }
ns.LQ2[2749] = { "O Ovomático disse: um ovo comum. Ainda há esperança.",
    "Crista aceita o ovo e torce pelo melhor." }
ns.LQ2_EN[2749] = { "The Egg-O-Matic says: an ordinary egg. There is still hope.",
    "Curgle takes the egg and hopes for the best." }
ns.LQ2[2750] = { "O Ovomático disse: estragado.",
    "Não dá para salvar todos, diz Crista. Volte a Feralas e tente de novo." }
ns.LQ2_EN[2750] = { "The Egg-O-Matic says: gone bad.",
    "We can't save them all, says Curgle. Go back to Feralas and try again." }
ns.LQ2[2872] = { "MacKinley, o Lobo do Mar, da Angra do Butim, apostou com o velho amigo Esmirno que o rum do Porto de Bondebico não é mais forte que o dele. Esmirno prometeu uma garrafa e sumiu. MacKinley quer que você cobre.",
    "Esmirno jura que não está com medo de perder a aposta. Ele só não tem rum nenhum." }
ns.LQ2_EN[2872] = { "\"Sea Wolf\" MacKinley of Booty Bay bet his old friend Stoley that Steamwheedle Port's rum is no stronger than his. Stoley promised a bottle and went quiet. MacKinley wants you to collect.",
    "Stoley swears he isn't afraid of losing the bet. He just hasn't got any rum." }
ns.LQ2[2873] = { "O último carregamento de rum de Esmirno foi roubado pelo Capitão Cuergo e está guardado na cidade pirata murada, ao sul. Sem ele, a aposta não se resolve.",
    "O rum está de volta. Agora a aposta pode ser decidida." }
ns.LQ2_EN[2873] = { "Stoley's last shipment of rum was stolen by Captain Cuergo and is stowed in the walled pirate town to the south. Without it, the bet can't be settled.",
    "The rum is back. Now the bet can be decided." }
ns.LQ2[2874] = { "Esmirno te entrega uma garrafa de rum de porão do Porto de Bondebico para MacKinley provar.",
    "MacKinley prova e quase engasga: é horrível. Ótimo! Grosso como cascalho, queima como lava. Esmirno ganhou." }
ns.LQ2_EN[2874] = { "Stoley hands you a bottle of Steamwheedle bilge rum for MacKinley to taste.",
    "MacKinley tastes it and nearly chokes: it's terrible. Wonderful! Thick as gravel, burns like lava. Stoley wins." }
ns.LQ2[8366] = { "Os piratas dos Mares do Sul pararam de respeitar o dinheiro de proteção que o Cartel paga. O Chefe de Segurança Silvadágua não pode sair do porto e nomeia você ajudante temporário para dar uma lição na enseada ao sul.",
    "O Cartel vai largar do pé de Silvadágua. Ele paga e deixa você escolher a recompensa." }
ns.LQ2_EN[8366] = { "The Southsea pirates have stopped honouring the protection money the Cartel pays. Security Chief Bilgewhizzle can't leave the port and deputises you to teach the cove to the south a lesson.",
    "The Cartel will get off Bilgewhizzle's back now. He pays and lets you choose your reward." }
ns.LQ2[8365] = { "Sissi Ashando veste reis, rainhas e chefes guerreiros — e cobra caro. A nova moda é chapéu de pirata, e ela quer vinte, tirados dos piratas dos Mares do Sul da enseada.",
    "Sissi limpa, personaliza e vende os chapéus por uma fortuna. Te dá um agrado e sugere um banho." }
ns.LQ2_EN[8365] = { "Haughty Modiste dresses kings, queens and warchiefs — and charges dearly. The new fashion is pirate hats, and she wants twenty, taken from the Southsea pirates in the cove.",
    "Modiste will clean, personalise and sell the hats for a fortune. She gives you a little something and suggests a bath." }
ns.LQ2[2875] = { "O pirata André Barbarruiva é procurado por crimes contra o Porto de Bondebico e Geringontzan. O cartaz autoriza força letal, e, se ele morrer antes do julgamento, a cabeça serve de representante.",
    "Silvadágua recebe a cabeça: André vai ao julgamento, afinal. Assine aqui, diz ele, e não ligue para as letras miúdas." }
ns.LQ2_EN[2875] = { "The pirate Andre Firebeard is wanted for crimes against Steamwheedle Port and Gadgetzan. The poster authorises lethal force, and should he die before his hearing, his head may stand in for him.",
    "Bilgewhizzle receives the head: Andre makes his trial after all. Sign here, he says, and never mind the small print." }
ns.LQ2[2876] = { "Um pirata carregava uma lista com as partidas e chegadas de navios entre o Porto de Bondebico e a Angra do Butim, com anotações como \"bom saque\" e \"luta dura\". Alguém no porto precisa ver isso.",
    "Silvadágua fica pálido: com esse papel, um capitão pirata faria a festa. Ainda bem que o dono está comendo areia." }
ns.LQ2_EN[2876] = { "A pirate was carrying a list of ship departures and arrivals between Steamwheedle Port and Booty Bay, annotated with notes like \"great loot\" and \"hard fight\". Someone at the port needs to see this.",
    "Bilgewhizzle goes pale: with this paper, a pirate captain would have a field day. Good thing its owner is eating sand." }
ns.LQ2[2882] = { "Um mapa com uma praia virada para o sul e uma rima: ao sul do porto, procure o mastro, a bandeira e os ossos, cave ali — e precisa de uma chave. É o ouro escondido do Capitão Cuergo.",
    "O tesouro de Cuergo está ali, esperando." }
ns.LQ2_EN[2882] = { "A map of a south-facing beach and a rhyme: south of the port, find the mast, the flag and the bones, dig there — and you'll need a key. It is Captain Cuergo's hidden gold.",
    "Captain Cuergo's treasure lies there, waiting." }
ns.LQ2[9268] = { "Rumsen Xabudega, no Porto de Bondebico, mantém a conta da guerra do Cartel contra os piratas no mar. Ele aceita tudo o que prove que você está do lado certo.",
    "Rumsen anota mais uma. Goblins não esquecem." }
ns.LQ2_EN[9268] = { "Rumsen Fizzlebrack, at Steamwheedle Port, keeps the tally of the Cartel's war against the pirates at sea. He takes anything that proves you are on the right side.",
    "Rumsen notes down another. Goblins don't forget." }
ns.LQ2[97530] = { "Alguém perdeu um bracelete muito brilhante perto do complexo dos ogros Dunamalho, e o Chefe de Segurança Silvadágua quer de volta. De quem é, ele não diz.",
    "Silvadágua guarda o bracelete rápido e muda de assunto." }
ns.LQ2_EN[97530] = { "Someone lost a very shiny bangle near the Dunemaul ogre compound, and Security Chief Bilgewhizzle wants it back. Whose it is, he doesn't say.",
    "Bilgewhizzle pockets the bangle quickly and changes the subject." }
ns.LQ2[1560] = { "Tuga, uma tartaruga, saiu para buscar o jantar e se perdeu. A mulher dele, Tarta, espera logo ao sul do Porto de Bondebico. Ele é lento. Muito lento.",
    "Tarta não se surpreende nada: claro que ele não achou o caminho sozinho." }
ns.LQ2_EN[1560] = { "Tooga, a turtle, went out to fetch dinner and got lost. His wife, Torta, is waiting just south of Steamwheedle Port. He is slow. Very slow.",
    "Torta is not surprised in the least: of course he couldn't find his way back alone." }
ns.LQ2[97540] = { "Tuga se perdeu de novo — desta vez depois de parar num oásis e beber até matar a sede. Bem hidratado e sem nenhum senso de direção, ele precisa de alguém que o leve de volta a Tarta.",
    "Tarta revira os olhos. Pelo menos ele chegou molhado." }
ns.LQ2_EN[97540] = { "Tooga is lost again — this time after stopping at an oasis and drinking his fill. Well watered and with no sense of direction, he needs someone to lead him back to Torta.",
    "Torta rolls her eyes. At least he came back wet." }
ns.LQ2[3520] = { "Yeh'kinya, no Porto de Bondebico, quer os espíritos dos guinchadores do vale de Feralas, primos de um deus muito antigo. Ele te dá uma varinha de espinheiro para recolher a essência deles.",
    "Yeh'kinya fala então da profecia: Hakkar, o Esfolador de Almas, vai voltar. Ele diz não acreditar. Mas quer manter esse poder longe de quem abusaria dele." }
ns.LQ2_EN[3520] = { "Yeh'kinya, at Steamwheedle Port, wants the spirits of the vale screechers of Feralas, cousins of a very old god. He gives you a bramble wand to gather their essence.",
    "Yeh'kinya then speaks of the prophecy: Hakkar the Soulflayer will return. He says he doesn't believe it. But he wants that power kept from those who would abuse it." }
ns.LQ2[8182] = { "O pior aconteceu. O Prospector Botaférrea lembra a lenda: o Esfolador de Almas governou o antigo mundo troll pelo terror, e se voltar pode dominar Azeroth. Os trolls Zandalari acamparam na Ilha Yojamba, na costa da Selva do Espinhaço. O líder deles, Molthor, talvez saiba como vencê-lo.",
    "Molthor recebe você: os Zandalari conhecem um caminho para derrotar Hakkar. Mas o que vem pela frente é encharcado de sangue." }
ns.LQ2_EN[8182] = { "The worst has come. Prospector Ironboot recalls the legend: the Soulflayer ruled the ancient troll world through terror, and if he returns he may rule Azeroth. The Zandalari trolls have camped on Yojamba Isle off the coast of Stranglethorn. Their leader, Molthor, may know how to beat him.",
    "Molthor receives you: the Zandalari know a way to defeat Hakkar. But the road ahead is soaked in blood." }
ns.LQ2[3161] = { "Marlon Catarrebite é cientista e caçador de tesouros. Os trolls que viviam aqui faziam ornamentos de um mineral que ele chama Gahz'ridian, em homenagem a Gahz'rilla, a hidra que adoravam. Ele inventou até um capacete detector.",
    "Os ornamentos são perfeitos para os estudos de Marlon. E ele quer o capacete de volta." }
ns.LQ2_EN[3161] = { "Marvon Rivetseeker is a scientist and a treasure hunter. The trolls who lived here carved ornaments from a mineral he calls Gahz'ridian, after Gahz'rilla, the hydra they worshipped. He even invented a detector helmet.",
    "The ornaments are perfect for Marvon's studies. And he'd like his helmet back." }
ns.LQ2[3444] = { "Marlon entrou no Templo Submerso uma vez e saiu por pouco. Lembra de uma sala redonda cheia de estátuas de serpentes — e encontrou depois uma pedra com o mesmo símbolo, despachada para a oficina dele em Vila Catraca.",
    "Com o círculo de pedra na mão, a memória de Marlon volta." }
ns.LQ2_EN[3444] = { "Marvon went into the Sunken Temple once and barely got out. He remembers a round room full of serpent statues — and later found a stone bearing the same symbol, shipped to his workshop in Ratchet.",
    "With the stone circle in hand, Marvon's memory comes back." }
ns.LQ2[2954] = { "Os discos de platina trazidos de Uldaman fizeram efeito: no deserto, o Vigia Pétreo de Norgannon desperta. Ele guarda a entrada de Uldum e só deixa passar quem tiver as Placas de Uldum.",
    "O vigia avisa: os discos voltam quando você usar o pedestal. Com as placas, a passagem se abre." }
ns.LQ2_EN[2954] = { "The platinum discs brought from Uldaman have done their work: in the desert, the Stone Watcher of Norgannon awakens. He guards the entrance to Uldum and lets through only those who carry the Plates of Uldum.",
    "The watcher warns you: your discs come back when you use the pedestal. With the plates, the way will open." }
ns.LQ2[95753] = { "No meio das Areias Abissais, ao lado de um esqueleto gigantesco, um totem estranho espera. Quem o toca vira lobo fantasma e tem pouco tempo para correr até o outro totem, na ponta do esqueleto, sem ser atingido.",
    "Você chega ao segundo totem, ofegante. O desafio do lobo do deserto está cumprido." }
ns.LQ2_EN[95753] = { "In the middle of the Abyssal Sands, beside a gigantic skeleton, an odd totem waits. Whoever touches it becomes a ghost wolf and has little time to run to the other totem, at the far end of the skeleton, without being hit.",
    "You reach the second totem, out of breath. The challenge of the desert wolf is done." }
ns.LQ2[96912] = { "Uízqui Gaseifipó organiza duelos em Tanaris e mantém o placar da semana. Para entrar no campo de honra, é preciso vencer dez.",
    "Dez vitórias no placar de Uízqui. Semana encerrada." }
ns.LQ2_EN[96912] = { "Wizzik Dustfizz runs duels in Tanaris and keeps the week's scoreboard. To make it onto the field of honour, you need to win ten.",
    "Ten wins on Wizzik's board. The week is done." }
ns.LQ2[5802] = { "Rugov A. Massoaço vende o molde da chave-mestra, mas o calor para fundir tório e osso só existe no lago de lava do Pico Penacho de Fogo, na Cratera Un'Goro. As barras de tório são problema seu.",
    "A chave está forjada, mas inacabada. O Boticário Trépido diz o que falta: enfrentar Araj, o Invocador, o lich que manda nas ruínas de Andorhal." }
ns.LQ2_EN[5802] = { "Krinkle Goodsteel sells the skeleton key mould, but the heat to fuse thorium and bone exists only in the lava lake atop Fire Plume Ridge in Un'Goro Crater. The thorium bars are your problem.",
    "The key is forged but unfinished. Apothecary Dithers tells you what remains: facing Araj the Summoner, the lich who rules the ruins of Andorhal." }
ns.LQ2[8923] = { "Mokvar, em Orgrimmar, quer falar com os mortos — com Anthion, mais precisamente. As amostras de veneno que você juntou são para um conhecido dele em Geringontzan, Mux Zoamana, engenheiro do sobrenatural.",
    "Mux recebe o veneno bem na hora: estava acabando. E quer saber mais de Mokvar." }
ns.LQ2_EN[8923] = { "Mokvar, in Orgrimmar, wants to speak with the dead — with Anthion, to be precise. The venom samples you gathered are for an acquaintance of his in Gadgetzan, Mux Manascrambler, an engineer of the supernatural.",
    "Mux gets the venom just in time: he was running low. And he wants to hear more about Mokvar." }
ns.LQ2[8921] = { "O projeto de Mux é um revelador de fantasmas extradimensional, e o primeiro passo é um destilador que colhe o próprio tecido da morte. A lista de peças é longa, e inclui cinza vulcânica das Estepes Ardentes e quarenta peças de ouro.",
    "Mux monta o destilador em instantes e te dá um agrado pelo trabalho." }
ns.LQ2_EN[8921] = { "Mux's project is an extra-dimensional ghost revealer, and the first step is a distiller that harvests the very fabric of death. The parts list is long, and includes volcanic ash from the Burning Steppes and forty gold.",
    "Mux assembles the distiller in moments and gives you something for your trouble." }
ns.LQ2[8924] = { "Cada clima deixa o ectoplasma de um jeito. Mux quer o chamuscado dos elfos atormentados de Silithus, o congelado dos espíritos de Hibérnia e o estável dos fantasmas das Terras Pestilentas Orientais.",
    "Com essas três energias, diz Mux, vai dar para alcançar almas que ainda não deixaram o mundo." }
ns.LQ2_EN[8924] = { "Every climate leaves ectoplasm differently. Mux wants the scorched kind from the tormented elves of Silithus, the frozen kind from the spirits of Winterspring, and the stable kind from the ghosts of the Eastern Plaguelands.",
    "With those three energies, says Mux, it will be possible to reach souls that haven't quite left the world." }
ns.LQ2[8925] = { "O ectoplasma precisa de uma fonte de energia estável. Mux ouviu falar de Bokk, Senhor do Magma, nas Estepes Ardentes, cujo coração é um núcleo de magma que nunca esfria.",
    "O núcleo de Bokk dá energia de sobra para o revelador." }
ns.LQ2_EN[8925] = { "The ectoplasm needs a stable power source. Mux has heard of Magma Lord Bokk, in the Burning Steppes, whose heart is a magma core that never cools.",
    "Bokk's core gives the revealer power to spare." }
ns.LQ2[8928] = { "Falta um bastão que conduza a energia sem derreter. Mux conheceu um diabrete numa caverna na entrada da Garganta do Sussurro Sombrio, em Hibérnia, que vendia um bastão elemental vil — e se arrepende de não ter comprado. Preço combinado: quarenta peças de ouro.",
    "O bastão serve perfeitamente. Agora é montar tudo." }
ns.LQ2_EN[8928] = { "What's missing is a rod to channel the energy without melting. Mux met an imp in a cave at the mouth of Darkwhisper Gorge, in Winterspring, who sold a fel elemental rod — and regrets not buying it. The agreed price: forty gold.",
    "The rod is perfect. Now to put it all together." }
ns.LQ2[8576] = { "Azuregos te deu um livro-razão em dracônico com o projeto de uma boia de arcanita. Narain Suavestilo, o vidente, pode fazê-la — se conseguir ler. Para isso ele precisa dos óculos de vidência, de um frango de 250 quilos e do volume II de Dracônico para Leigos.",
    "Narain faz a lista e não explica nada. Primeiro, o básico." }
ns.LQ2_EN[8576] = { "Azuregos gave you a ledger in Draconic with the design for an arcanite buoy. Narain Soothfancy, the seer, can make it — if he can read it. For that he needs his scrying goggles, a five-hundred-pound chicken and volume two of Draconic for Dummies.",
    "Narain makes his list and explains nothing. Basics first." }
ns.LQ2[8577] = { "Os óculos de vidência de Narain foram roubados pelo ex-melhor amigo dele, Stewvul, que partiu o coração do gnomo em cinco lugares. A bola de cristal aponta duas possibilidades: a Muralha Greymane, em Silverpine, ou um mundo invadido pela Legião em Terralém.",
    "Stewvul se escondia num caixote inconspícuo e jura que não volta a ser o escravo de meio período de ninguém." }
ns.LQ2_EN[8577] = { "Narain's scrying goggles were stolen by his ex-best friend forever, Stewvul, who broke the gnome's heart in five places. The crystal ball points to two places: the Greymane Wall in Silverpine, or a Legion-overrun world in Outland.",
    "Stewvul was hiding in an inconspicuous crate and swears he is through being anyone's part-time slave." }
ns.LQ2[8584] = { "Nunca pergunte a Narain sobre o trabalho dele. Ele precisa de um frango de 250 quilos, e quem sabe onde achar um é Funesto Marrão, o açougueiro de Geringontzan.",
    "Funesto coça a cabeça: um frango assim não existe mais. Mas ele tem uma ideia que serve aos dois." }
ns.LQ2_EN[8584] = { "Never ask Narain about his business. He needs a five-hundred-pound chicken, and the one who knows where to find one is Dirge Quikcleave, Gadgetzan's butcher.",
    "Dirge scratches his head: no chicken like that exists any more. But he has an idea that works for both of you." }
ns.LQ2[8585] = { "Os quimérocos da Ilha do Medo, em Feralas, têm a carne mais macia do mundo, e o pai deles, Lakmaeran, bem preparado, pode passar por um frango de 250 quilos. Funesto quer a carcaça e vinte lombos.",
    "Funesto admira o marmorizado dos lombos e vai pensar na receita." }
ns.LQ2_EN[8585] = { "The chimaerok of the Isle of Dread, in Feralas, have the most tender meat in the world, and their sire, Lakmaeran, properly prepared, might pass for a five-hundred-pound chicken. Dirge wants the carcass and twenty tenderloins.",
    "Dirge admires the marbling on the tenderloins and goes off to devise the recipe." }
ns.LQ2[8586] = { "A receita está pronta. Funesto precisa de combustível de foguete goblínico e sal de rocha funda; o tempero é com ele.",
    "Funesto apresenta a maior criação dele: as Costeletas Sinistronas de Quiméroco." }
ns.LQ2_EN[8586] = { "The recipe is ready. Dirge needs goblin rocket fuel and deeprock salt; the seasoning is up to him.",
    "Dirge presents his greatest creation: Dirge's Kickin' Chimaerok Chops." }
ns.LQ2[8587] = { "Palavra de goblin: aqui está o frango de 250 quilos. Funesto resmunga que gnomo deve querer aquilo para dormir dentro.",
    "Narain enfia as duas mãos no frango e come como se não houvesse amanhã. O melhor frango da vida dele." }
ns.LQ2_EN[8587] = { "A goblin's word: here is the five-hundred-pound chicken. Dirge grumbles that a gnome probably wants it to sleep in.",
    "Narain plunges both fists into the chicken and eats like there's no tomorrow. Best chicken he's ever had." }
ns.LQ2[8597] = { "Narain escondeu o livro num lugar que ninguém acharia: uma ilha nos Mares do Sul, aonde só chegou de girocóptero. Na volta, caiu na praia — e foi assim que ganhou os poderes psíquicos. Siga do girocóptero acidentado para o sul.",
    "O livro sumiu. No monte de terra, um bilhete." }
ns.LQ2_EN[8597] = { "Narain hid the book where no one would find it: an island in the South Seas he could only reach by gyrocopter. On the way back he crashed on the beach — which is how he got his psychic powers. Swim south from the wrecked gyrocopter.",
    "The book is gone. On top of the dirt mound, a note." }
ns.LQ2[8598] = { "O bilhete é feito de letras recortadas: temos o seu livro, gnomo. Traga o dinheiro e venha sozinho. As instruções ocupam três páginas.",
    "Narain fica vermelho. Sequestrar o livro dele? Vão aprender a não mexer com um gnomo psíquico." }
ns.LQ2_EN[8598] = { "The note is made of cut-out letters: we have your book, gnome. Bring the money and come alone. The instructions run to three pages.",
    "Narain turns bright red. Booknap his book? They'll learn not to mess with a psychic gnome." }
ns.LQ2[8606] = { "O plano de Narain: um saco cheio de pedras, um turbante, um manto, e você no lugar dele no ponto de entrega em Hibérnia. Quando os sequestradores aparecerem, acabe com eles.",
    "Narain admite: talvez tenham subestimado esses sequestradores." }
ns.LQ2_EN[8606] = { "Narain's plan: a sack full of rocks, a turban, a robe, and you in his place at the drop-off point in Winterspring. When the booknappers show up, snuff them out.",
    "Narain admits it: perhaps they underestimated these booknappers." }
ns.LQ2[8620] = { "Era o arqui-inimigo de Narain, o Doutor Weavil. Por causa do fracasso em Hibérnia, o único exemplar do livro foi rasgado em oito partes e espalhado pelo vento. Narain te dá uma capa mágica para juntar tudo de novo.",
    "Narain tira o turbante para você. Ele teria deixado o mundo implodir." }
ns.LQ2_EN[8620] = { "It was Narain's arch-enemy, Doctor Weavil. Thanks to the failure in Winterspring, the only copy of the book was torn into eight parts and scattered to the wind. Narain gives you a magical binding to put it back together.",
    "Narain tips his turban to you. He'd have let the world implode." }
ns.LQ2[8599] = { "Na ilha dos Mares do Sul vive Meridith, a sereia que salvou Narain dos destroços do girocóptero. Desde então ela não pensa em outra coisa, e pede que você leve uma carta de amor a ele.",
    "Narain se remexe: ela é um peixe! Um peixe! E ele é um gnomo. Não ia dar certo." }
ns.LQ2_EN[8599] = { "On the South Seas island lives Meridith, the mermaid who rescued Narain from the gyrocopter wreck. She has thought of nothing else since, and asks you to take him a love letter.",
    "Narain fidgets: she's a fish! A fish! And he's a gnome. It could never work." }
ns.LQ2[8728] = { "Com óculos, frango e livro, Narain enfim lê o livro-razão. A boa notícia: ele é 99% capaz de fazer a boia. A má: vai precisar de muita arcanita, elemêntio e pedras preciosas raras.",
    "Trato é trato. Narain entrega a boia e comenta que é muito trabalho só para pescar." }
ns.LQ2_EN[8728] = { "With goggles, chicken and book, Narain finally reads the ledger. The good news: he is ninety-nine percent sure he can make the buoy. The bad news: he'll need a great deal of arcanite, elementium and rare gems.",
    "A deal is a deal. Narain hands over the buoy and remarks that it's an awful lot of trouble just to go fishing." }
ns.LQ2[8555] = { "Nas Cavernas do Tempo, Anacronos fala de Eranikus, Vaelastrasz e Azuregos, três dragões que vigiaram o mundo e caíram em tragédias, por agentes dos Deuses Antigos ou traição de quem chamavam de amigos. Procure-os, diz ele, e prepare-se para o pior.",
    "O caminho do cetro começa com esses três nomes." }
ns.LQ2_EN[8555] = { "In the Caverns of Time, Anachronos speaks of Eranikus, Vaelastrasz and Azuregos, three dragons who watched over the world and fell to tragedy, through agents of the Old Gods or the betrayal of those they called friends. Seek them out, he says, and prepare for the worst.",
    "The road to the scepter begins with those three names." }
ns.LQ2[8742] = { "Mil anos se passaram e, como estava escrito, alguém está diante de Anacronos para conduzir o seu povo a uma nova era. O Deus Antigo treme. Quando você estiver pronto, ele entrega o Cetro das Areias Movediças.",
    "O cetro está inteiro. Só você pode usá-lo — quando os exércitos da Horda e da Aliança chegarem a Silithus, toque o Gongo do Escaravelho." }
ns.LQ2_EN[8742] = { "A thousand years have passed and, as was fated, someone stands before Anachronos to lead their people into a new age. The Old God trembles. When you are ready, he grants the Scepter of the Shifting Sands.",
    "The scepter is whole. Only you may use it — once the armies of the Horde and the Alliance reach Silithus, ring the Scarab Gong." }
ns.LQ2[9250] = { "Com a armação formada, Atiesh está quase inteiro. Faltam a ponta e a base — e há o pequeno problema de o cajado ser um canal para o mal de Sargeras. Alguém precisa ajudar.",
    "Anacronos conta que os arquimagos morreram, e que não é para lamentar: estava escrito, como estava escrito que você teria o cajado do Guardião." }
ns.LQ2_EN[9250] = { "With the frame formed, Atiesh is nearly whole. The head and base are missing — and there is the small matter of the staff being a conduit for Sargeras's evil. Someone has to help.",
    "Anachronos says the archmages have died, and that there is no cause to mourn: it was fated, just as it was fated that you would hold the Guardian's staff." }
ns.LQ2[9251] = { "Anacronos sabe onde estão as peças: a ponta, com Kel'Thuzad, em Naxxramas; a base, em Ahn'Qiraj, onde Brann Barbabronze a deixou.",
    "Com as peças reunidas, Anacronos sente algo lá dentro. Um ser que não é deste mundo." }
ns.LQ2_EN[9251] = { "Anachronos knows where the pieces are: the head, with Kel'Thuzad in Naxxramas; the base, in Ahn'Qiraj, where Brann Bronzebeard left it.",
    "With the pieces together, Anachronos senses something within. A being not of this world." }
ns.LQ2[8752] = { "A Prole de Nozdormu reconhece o que você fez em Ahn'Qiraj. Anacronos oferece o caminho do conquistador, com um anel que fortalece os ataques físicos. Escolhido o caminho, não há volta.",
    "O anel do conquistador é seu." }
ns.LQ2_EN[8752] = { "The Brood of Nozdormu recognises what you have done in Ahn'Qiraj. Anachronos offers the path of the conqueror, with a ring that strengthens physical attacks. Once the path is chosen, there is no turning back.",
    "The conqueror's ring is yours." }
ns.LQ2[8753] = { "A sua posição na Prole subiu. Anacronos fortalece o anel do conquistador.",
    "Que você nunca deixe o caminho do conquistador." }
ns.LQ2_EN[8753] = { "Your standing with the Brood has risen. Anachronos strengthens the conqueror's ring.",
    "May you never stray from the path of the conqueror." }
ns.LQ2[8754] = { "Mais um passo na Prole de Nozdormu, mais força no anel do conquistador.",
    "Anacronos se impressiona com a sua ascensão." }
ns.LQ2_EN[8754] = { "One more step with the Brood of Nozdormu, more strength in the conqueror's ring.",
    "Anachronos is impressed by your rise." }
ns.LQ2[8755] = { "A Prole reconhece de novo o seu valor. O anel do conquistador cresce outra vez.",
    "O caminho do conquistador continua." }
ns.LQ2_EN[8755] = { "The Brood recognises your worth once more. The conqueror's ring grows again.",
    "The path of the conqueror goes on." }
ns.LQ2[8756] = { "No topo da Prole de Nozdormu, Anacronos chama você para o último passo.",
    "Levante-se, Conquistador Qiraji, e seja reconhecido." }
ns.LQ2_EN[8756] = { "At the height of the Brood of Nozdormu, Anachronos calls you to the final step.",
    "Rise, Qiraji Conqueror, and be recognised." }
ns.LQ2[8766] = { "Se quiser trocar de caminho, Anacronos devolve o anel do conquistador e deixa a escolha aberta de novo.",
    "Anacronos se despede: se mudar de ideia, ele estará aqui." }
ns.LQ2_EN[8766] = { "If you wish to change paths, Anachronos takes back the conqueror's ring and leaves the choice open again.",
    "Anachronos bids you well: should you change your mind, he will be here." }
ns.LQ2[8757] = { "A Prole de Nozdormu reconhece o que você fez em Ahn'Qiraj. Anacronos oferece o caminho do evocador, com um anel que fortalece as habilidades mágicas e naturais. Escolhido o caminho, não há volta.",
    "O anel do evocador é seu." }
ns.LQ2_EN[8757] = { "The Brood of Nozdormu recognises what you have done in Ahn'Qiraj. Anachronos offers the path of the invoker, with a ring that strengthens magical and natural abilities. Once the path is chosen, there is no turning back.",
    "The invoker's ring is yours." }
ns.LQ2[8758] = { "A sua posição na Prole subiu. Anacronos fortalece o anel do evocador.",
    "Que você nunca deixe o caminho do evocador." }
ns.LQ2_EN[8758] = { "Your standing with the Brood has risen. Anachronos strengthens the invoker's ring.",
    "May you never stray from the path of the invoker." }
ns.LQ2[8759] = { "Mais um passo na Prole de Nozdormu, mais força no anel do evocador.",
    "Anacronos se impressiona com a sua ascensão." }
ns.LQ2_EN[8759] = { "One more step with the Brood of Nozdormu, more strength in the invoker's ring.",
    "Anachronos is impressed by your rise." }
ns.LQ2[8760] = { "A Prole reconhece de novo o seu valor. O anel do evocador cresce outra vez.",
    "O caminho do evocador continua." }
ns.LQ2_EN[8760] = { "The Brood recognises your worth once more. The invoker's ring grows again.",
    "The path of the invoker goes on." }
ns.LQ2[8761] = { "No topo da Prole de Nozdormu, Anacronos chama você para o último passo.",
    "Levante-se, Grande Evocador, e seja reconhecido." }
ns.LQ2_EN[8761] = { "At the height of the Brood of Nozdormu, Anachronos calls you to the final step.",
    "Rise, Grand Invoker, and be recognised." }
