ns.LQ2[8747] = { "A Prole de Nozdormu reconhece o que você fez em Ahn'Qiraj. Anacronos oferece o caminho do protetor, com um anel que protege contra as forças do mal. Escolhido o caminho, não há volta.",
    "O anel do protetor é seu." }
ns.LQ2_EN[8747] = { "The Brood of Nozdormu recognises what you have done in Ahn'Qiraj. Anachronos offers the path of the protector, with a ring that shields against the forces of evil. Once the path is chosen, there is no turning back.",
    "The protector's ring is yours." }
ns.LQ2[8748] = { "A sua posição na Prole subiu. Anacronos fortalece o anel do protetor.",
    "Que você nunca deixe o caminho do protetor." }
ns.LQ2_EN[8748] = { "Your standing with the Brood has risen. Anachronos strengthens the protector's ring.",
    "May you never stray from the path of the protector." }
ns.LQ2[8749] = { "Mais um passo na Prole de Nozdormu, mais força no anel do protetor.",
    "Anacronos se impressiona com a sua ascensão." }
ns.LQ2_EN[8749] = { "One more step with the Brood of Nozdormu, more strength in the protector's ring.",
