ns.LQ2_EN[8750] = { "The Brood recognises your worth once more. The protector's ring grows again.",
    "The path of the protector goes on." }
ns.LQ2[8751] = { "No topo da Prole de Nozdormu, Anacronos chama você para o último passo.",
    "Levante-se, Protetor de Kalimdor, e seja reconhecido." }
ns.LQ2_EN[8751] = { "At the height of the Brood of Nozdormu, Anachronos calls you to the final step.",
    "Rise, Protector of Kalimdor, and be recognised." }
ns.LQ2[8764] = { "Se quiser trocar de caminho, Anacronos devolve o anel do protetor e deixa a escolha aberta de novo.",
    "Anacronos se despede: se mudar de ideia, ele estará aqui." }
ns.LQ2_EN[8764] = { "If you wish to change paths, Anachronos takes back the protector's ring and leaves the choice open again.",
    "Anachronos bids you well: should you change your mind, he will be here." }
ns.LQ2[351] = { "Na areia, um ovo de metal. Mexendo num botão, ele se abre num aparelho gnômico, e uma voz chia lá de dentro: é Olhatorto, e o robô teleguiado dele sumiu. O transmissor já calculou: caiu perto do grande abismo de Tanaris.",
    "O robô liga, mas precisa de conserto. É pesado demais para carregar, e Olhatorto tem uma ideia." }
ns.LQ2_EN[351] = { "In the sand, a metal egg. Turning a knob springs it open into a gnomish contraption, and a voice crackles from inside: it is Oglethorpe, and his homing robot has gone missing. The beacon has worked it out: it crashed near Tanaris's great chasm.",
    "The robot powers on but needs repairs. It's too heavy to carry, and Oglethorpe has an idea." }
ns.LQ2[648] = { "O OOX-17/TN precisa de um lugar aberto e seguro para decolar, e o camuflador dele demora para voltar a funcionar. Olhatorto pede que você o escolte até o Porto de Bondebico e depois vá vê-lo na Angra do Butim.",
    "Olhatorto não sabe como agradecer: você poupou horas de reconstrução e muito ouro. Escolha uma das coisas dele." }
ns.LQ2_EN[648] = { "OOX-17/TN needs an open, safe place for take-off, and its cloaking takes time to come back online. Oglethorpe asks you to escort it to Steamwheedle Port and then come and see him in Booty Bay.",
    "Oglethorpe can't thank you enough: you saved him hours of rebuilding and a great deal of gold. Take your pick of his things." }
